func poolsterSequentialMedia(contentType string) bool {
	media := strings.ToLower(strings.TrimSpace(strings.Split(contentType, ";")[0]))
	return media == "application/x-ndjson" || media == "application/ndjson" || media == "application/jsonl" || media == "application/json-seq" || strings.HasSuffix(media, "+json-seq")
}

type poolsterSequentialBody struct {
	ContentType string
	Value       any
}

func encodePoolsterSequential(body poolsterSequentialBody) ([]byte, string, error) {
	encoded, err := json.Marshal(body.Value)
	if err != nil {
		return nil, "", err
	}
	var records []json.RawMessage
	if err = json.Unmarshal(encoded, &records); err != nil {
		return nil, "", fmt.Errorf("poolster: sequential request requires an array: %w", err)
	}
	var output bytes.Buffer
	media := strings.ToLower(strings.TrimSpace(strings.Split(body.ContentType, ";")[0]))
	for _, record := range records {
		if media == "application/json-seq" || strings.HasSuffix(media, "+json-seq") {
			output.WriteByte(0x1e)
		}
		output.Write(record)
		output.WriteByte('\n')
		if output.Len() > 10<<20 {
			return nil, "", fmt.Errorf("poolster: sequential request exceeds 10 MiB")
		}
	}
	return output.Bytes(), body.ContentType, nil
}

type poolsterQueryEncoding struct {
	ContentType   string `json:"contentType"`
	Style         string `json:"style"`
	Explode       *bool  `json:"explode"`
	AllowReserved bool   `json:"allowReserved"`
}

func poolsterQueryEscape(value string, reserved bool) string {
	escaped := url.QueryEscape(value)
	if reserved {
		for _, character := range ":/?#[]@!$&'()*+,;=" {
			escaped = strings.ReplaceAll(escaped, url.QueryEscape(string(character)), string(character))
		}
	}
	return escaped
}
func poolsterFormQueryField(pairs *[]string, name string, value any, encoding poolsterQueryEncoding) error {
	if value == nil {
		return nil
	}
	add := func(key, value string) {
		*pairs = append(*pairs, url.QueryEscape(key)+"="+poolsterQueryEscape(value, encoding.AllowReserved))
	}
	if array, ok := value.([]any); ok {
		if encoding.ContentType != "" {
			for _, item := range array {
				if err := poolsterFormQueryField(pairs, name, item, encoding); err != nil {
					return err
				}
			}
			return nil
		}
		explode := encoding.Explode == nil || *encoding.Explode
		if !explode || encoding.Style == "spaceDelimited" || encoding.Style == "pipeDelimited" {
			values := []string{}
			for _, item := range array {
				values = append(values, fmt.Sprint(item))
			}
			separator := ","
			if encoding.Style == "spaceDelimited" {
				separator = " "
			}
			if encoding.Style == "pipeDelimited" {
				separator = "|"
			}
			add(name, strings.Join(values, separator))
			return nil
		}
		for _, item := range array {
			if err := poolsterFormQueryField(pairs, name, item, encoding); err != nil {
				return err
			}
		}
		return nil
	}
	if encoding.ContentType != "" {
		if encoding.ContentType == "application/json" || strings.HasSuffix(encoding.ContentType, "+json") {
			encoded, err := json.Marshal(value)
			if err != nil {
				return err
			}
			add(name, string(encoded))
			return nil
		}
		if text, ok := value.(string); ok {
			add(name, text)
			return nil
		}
		return fmt.Errorf("poolster: query content type %s requires a serialized string", encoding.ContentType)
	}
	if object, ok := value.(map[string]any); ok {
		keys := make([]string, 0, len(object))
		for key := range object {
			keys = append(keys, key)
		}
		sort.Strings(keys)
		if encoding.Style == "deepObject" {
			for _, key := range keys {
				add(name+"["+key+"]", fmt.Sprint(object[key]))
			}
			return nil
		}
		if encoding.Explode == nil || *encoding.Explode {
			for _, key := range keys {
				add(key, fmt.Sprint(object[key]))
			}
			return nil
		}
		items := []string{}
		for _, key := range keys {
			items = append(items, key, fmt.Sprint(object[key]))
		}
		add(name, strings.Join(items, ","))
		return nil
	}
	add(name, fmt.Sprint(value))
	return nil
}

func poolsterParameterContent(value any, contentType string) (string, bool, error) {
	if value == nil {
		return "", false, nil
	}
	reflected := reflect.ValueOf(value)
	if reflected.Kind() == reflect.Pointer {
		if reflected.IsNil() {
			return "", false, nil
		}
		value = reflected.Elem().Interface()
	}
	media := strings.ToLower(strings.TrimSpace(strings.Split(contentType, ";")[0]))
	if media == "application/json" || strings.HasSuffix(media, "+json") {
		encoded, err := json.Marshal(value)
		return string(encoded), true, err
	}
	if text, ok := value.(string); ok {
		return text, true, nil
	}
	if media == "text/plain" {
		return fmt.Sprint(value), true, nil
	}
	return "", false, fmt.Errorf("poolster: parameter content type %s requires a serialized string", media)
}
// PoolsterMiddleware wraps the native HTTP execution boundary. Request context and
// response-body ownership follow net/http conventions. Wrappers may rewrite
// requests/responses, recover errors, or return a response without calling next.
// Middleware and its wrapped transport must support concurrent use.
type PoolsterMiddleware func(PoolsterHTTPClient) PoolsterHTTPClient

// PoolsterHTTPClientFunc adapts a function into an injectable transport.
type PoolsterHTTPClientFunc func(*http.Request) (*http.Response, error)

func (handler PoolsterHTTPClientFunc) Do(request *http.Request) (*http.Response, error) {
	return handler(request)
}
// PoolsterCallOptions scopes headers and a logical-call deadline to a context.
// A zero Timeout keeps the caller's deadline. A positive timeout can shorten it.
// Contexts reused for pagination share one deadline across all pages.
type PoolsterCallOptions struct {
	Headers http.Header
	Timeout time.Duration
}
type poolsterCallOptionsKey struct{}

// WithRequestOptions copies the headers; callers must defer the returned cancel.
// Explicit scoped headers override generated headers and static credentials.
func WithRequestOptions(ctx context.Context, options PoolsterCallOptions) (context.Context, context.CancelFunc, error) {
	if ctx == nil || options.Timeout < 0 {
		return nil, nil, fmt.Errorf("poolster: invalid request context or timeout")
	}
	scoped := context.WithValue(ctx, poolsterCallOptionsKey{}, options.Headers.Clone())
	if options.Timeout > 0 {
		scoped, cancel := context.WithTimeout(scoped, options.Timeout)
		return scoped, cancel, nil
	}
	scoped, cancel := context.WithCancel(scoped)
	return scoped, cancel, nil
}
func applyCallHeaders(request *http.Request) {
	headers, _ := request.Context().Value(poolsterCallOptionsKey{}).(http.Header)
	for name, values := range headers {
		request.Header.Del(name)
		for _, value := range values {
			request.Header.Add(name, value)
		}
	}
}

func encodePoolsterWireBody(body any) ([]byte,string,error) { if sequential,ok:=body.(poolsterSequentialBody);ok {return encodePoolsterSequential(sequential)}
encoded,err:=json.Marshal(body);return encoded,"application/json",err
}

// PoolsterTokenProvider supplies a token, refreshing only a rejected cached token.
type PoolsterTokenProvider interface { Token(context.Context, string) (string, error) }

// PoolsterHTTPClient is the replaceable execution boundary; context cancellation remains on the request.
type PoolsterHTTPClient interface { Do(*http.Request) (*http.Response, error) }
